def winner(t, head, keep_rows=None):
    rows = list(range(3 * head, 3 * head + 3))
    if keep_rows is not None:
        rows = [r for r in rows if r in keep_rows]
    # Symbolic hinge regions: each hidden unit contributes an affine term
    # on either side of its analytically derived breakpoint.
    active = (w0 * t + b0) > 0
    logits = [
        b1[r] + sum(float(w1[r, h]) * max(0.0, float(w0[h] * t + b0[h]))
                    for h in range(32))
        for r in rows
    ]
    return rows[max(range(len(rows)), key=lambda i: logits[i])]

