import itertools, json, bisect

b0 = [float(x) for x in W["target.b0"]]
b1 = [float(x) for x in W["target.b1"]]
a = [float(x) for x in W["target.w0"][:, 0]]
c = [[float(x) for x in row] for row in W["target.w1"]]

# Public weighted-code feature; enumerate only to count the declared Boolean
# decision regions, not to run network layers.
codes, positions = (2, 0, 1), (2, 1, 2, 1, 2)
domain = [
    sum(positions[i] * codes[s[i]] for i in range(n))
    for n in range(1, 6)
    for s in itertools.product(range(3), repeat=n)
]
assert len(domain) == 363

def compile_decision(head, retained_rows, scale):
    rows = list(range(3 * head, 3 * head + 3))
    lo, hi = min(domain) * scale, max(domain) * scale
    hinges = sorted({
        -b0[h] / a[h] for h in range(32)
        if a[h] != 0 and lo < -b0[h] / a[h] < hi
    })
    cuts = [lo] + hinges + [hi]
    pieces = []

    # On each hinge interval, coefficient identities give affine logits.
    for left, right in zip(cuts, cuts[1:]):
        mid = (left + right) / 2
        lines = {}
        for r in rows:
            if r not in retained_rows:
                lines[r] = (0.0, b1[r])
                continue
            slope, intercept = 0.0, b1[r]
            for h in range(32):
                if a[h] * mid + b0[h] > 0:
                    slope += c[r][h] * a[h]
                    intercept += c[r][h] * b0[h]
            lines[r] = (slope, intercept)

        # Add every pairwise affine crossing inside this hinge interval.
        extra = []
        for i, r in enumerate(rows):
            for q in rows[i + 1:]:
                m1, d1 = lines[r]
                m2, d2 = lines[q]
                if m1 != m2:
                    x = (d2 - d1) / (m1 - m2)
                    if left < x < right:
                        extra.append(x)
        subcuts = [left] + sorted(extra) + [right]
        for x, y in zip(subcuts, subcuts[1:]):
            probe = (x + y) / 2
            best = max(rows, key=lambda r: (lines[r][0] * probe + lines[r][1], -r))
            pieces.append((x, y, best, lines))

    boundaries = sorted({x for piece in pieces for x in piece[:2]})

    def classify(t):
        i = min(max(bisect.bisect_right(boundaries, t) - 1, 0), len(pieces) - 1)
        _, _, best, lines = pieces[i]
        # This is the compiled affine-threshold Boolean decision, not a layer.
        return best % 3

    return classify

def fraction(head, intervention):
    if intervention == "f0":
        scale, retained = 1.0, set(range(6))
    elif intervention == "f1":
        scale, retained = 0.67, set(range(6))
    elif intervention == "f2":
        scale, retained = 1.0, set(range(3))
    else:
        scale, retained = 0.67, set(range(3, 6))

    base = compile_decision(head, set(range(6)), 1.0)
    changed = compile_decision(head, retained, scale)
    return sum(base(float(s)) != changed(scale * float(s)) for s in domain) / 363

sub = {"effects": {
    f"f{i}": [fraction(0, f"f{i}"), fraction(1, f"f{i}")]
    for i in range(4)
}}
